  { x: '78%', y: '12%', size: 12, rotate: 15, delay: 0.1 },
  { x: '85%', y: '55%', size: 14, rotate: -10, delay: 0.15 },
  { x: '20%', y: '65%', size: 10, rotate: 20, delay: 0.2 },
  { x: '65%', y: '70%', size: 8, rotate: -5, delay: 0.25 },
]

const forkDecorations = [
