  return (
    <div className={cn('grid grid-cols-1 md:grid-cols-3 gap-4 w-fit', className)}>
      <GitHubStatsCard type="stars" label="GitHub stars" value={stars} />
      <GitHubStatsCard type="forks" label="Forks" value={forks} />
      <GitHubStatsCard type="commits" label="Commits" value={commits} />
    </div>
  )
}

import type { ContributionData, LighthouseScores, ThoughtItem, CategoryItem, ChangelogItem } from './types'

export function generateMockContributions(): ContributionData {
  const weeks = []
  const levels = ['NONE', 'FIRST_QUARTILE', 'SECOND_QUARTILE', 'THIRD_QUARTILE', 'FOURTH_QUARTILE'] as const
  let total = 0

  const now = new Date()
  for (let w = 51; w >= 0; w--) {
    const days = []
    for (let d = 0; d < 7; d++) {
      const date = new Date(now)
      date.setDate(date.getDate() - (w * 7 + (6 - d)))
      const rand = Math.random()
      const count = rand > 0.4 ? Math.floor(rand * 9) : 0
      total += count
      const level =
        count === 0 ? levels[0] : count < 3 ? levels[1] : count < 5 ? levels[2] : count < 8 ? levels[3] : levels[4]

      days.push({
        date: date.toISOString().split('T')[0],
        contributionCount: count,
        contributionLevel: level,
      })
    }
    weeks.push({ contributionDays: days })
  }

  return {
    totalContributions: total,
    weeks,
  }
}

